<?php
namespace App\Controllers;use App\Core\Database;use Throwable;
final class EventController{
 public function index():void{$db=Database::db();$events=$db->query("SELECT e.*,COUNT(DISTINCT p.id) photos_count,COUNT(DISTINCT ps.id) sets_count,MIN(p.id) cover_id,MIN(p.preview_path) preview_path FROM events e LEFT JOIN photos p ON p.event_id=e.id LEFT JOIN photo_sets ps ON ps.event_id=e.id GROUP BY e.id ORDER BY e.event_date DESC,e.id DESC")->fetchAll();$selected=null;if(!empty($_GET['id'])){$s=$db->prepare('SELECT * FROM events WHERE id=?');$s->execute([(int)$_GET['id']]);$selected=$s->fetch()?:null;}admin_view('admin/events',['events'=>$events,'selected'=>$selected,'pageTitle'=>'Eventos','adminSection'=>'events']);}
 public function save():never{verify_csrf();$db=Database::db();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$sport=trim($_POST['sport']??'');$date=$_POST['event_date']??'';$location=trim($_POST['location']??'');$status=in_array($_POST['status']??'',['draft','published','archived'],true)?$_POST['status']:'draft';if($name===''||$sport===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$_SESSION['error']='Completa nombre, disciplina y fecha.';redirect('/admin/eventos'.($id?'?id='.$id:''));}$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',iconv('UTF-8','ASCII//TRANSLIT',$name)?:$name),'-'));$check=$db->prepare('SELECT id FROM events WHERE slug=? AND id<>?');$check->execute([$slug,$id]);if($check->fetch())$slug.='-'.$id.'-'.substr(md5($name.$date),0,4);try{if($id)$db->prepare('UPDATE events SET name=?,slug=?,sport=?,event_date=?,location=?,status=? WHERE id=?')->execute([$name,$slug,$sport,$date,$location,$status,$id]);else{$db->prepare('INSERT INTO events(name,slug,sport,event_date,location,status) VALUES(?,?,?,?,?,?)')->execute([$name,$slug,$sport,$date,$location,$status]);$id=(int)$db->lastInsertId();}$_SESSION['success']='Evento guardado correctamente.';}catch(Throwable $e){error_log('Event save: '.$e->getMessage());$_SESSION['error']='No fue posible guardar el evento.';}redirect('/admin/eventos?id='.$id);}
 public function status():never{verify_csrf();$status=in_array($_POST['status']??'',['draft','published','archived'],true)?$_POST['status']:'draft';Database::db()->prepare('UPDATE events SET status=? WHERE id=?')->execute([$status,(int)$_POST['id']]);$_SESSION['success']='Estado del evento actualizado.';redirect('/admin/eventos');}
 public function delete():never{verify_csrf();$db=Database::db();$id=(int)$_POST['id'];$s=$db->prepare('SELECT (SELECT COUNT(*) FROM photos WHERE event_id=?)+(SELECT COUNT(*) FROM photo_sets WHERE event_id=?)');$s->execute([$id,$id]);if((int)$s->fetchColumn()>0){$db->prepare("UPDATE events SET status='archived' WHERE id=?")->execute([$id]);$_SESSION['success']='El evento tiene fotografías y fue archivado para conservar su historial.';}else{$db->prepare('DELETE FROM events WHERE id=?')->execute([$id]);$_SESSION['success']='Evento eliminado.';}redirect('/admin/eventos');}
}
